import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        v, u = map(int, sys.stdin.readline().split())
        adj[v].append(u)
        adj[u].append(v)

    parent = [0]*(n+1)
    children = [[] for _ in range(n+1)]
    q = deque([1])
    parent[1] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if parent[v] == 0 and v != parent[u]:
                parent[v] = u
                children[u].append(v)
                q.append(v)

    diff = [0]*(n+1)
    val = a.copy()

    def update(x, delta):
        while x != 0:
            diff[x] += delta
            x = parent[x]

    def query(x):
        res = val[x-1]
        while x != 0:
            res += diff[x]
            x = parent[x]
        return res

    for _ in range(m):
        parts = sys.stdin.readline().split()
        if parts[0] == '1':
            x, val_add = map(int, parts[1:])
            update(x, val_add)
            for child in children[x]:
                update(child, -val_add)
        else:
            x = int(parts[1])
            print(query(x))

if __name__ == '__main__':
    main()
